  'ios-ivx-ia/IVXIAUITests/IVXIAUITests.swift',
  'ios-ivx-ia/IVXIAUITests/IVXIAUITestsLaunchTests.swift',
];

let ok = 0, fail = 0;
const failures = [];

for (const path of files) {
  const content = readFileSync(path);
  const gz = gzipSync(content).toString('base64');
  const body = {
    action: 'github_commit_file',
    input: {
      path,
      content: gz,
      contentEncoding: 'gzip-base64',
      message: 'IVX vendor-independence closeout Phase 3: remove Rork branding from iOS Swift headers + fix appNone bundle ID bug + rewrite expo/README.md. 22 Swift "Created by Rork" → "Created by IVX Holdings"; 4 ContentView "Placeholder shown until Rork replaces it" → "until the real app UI is generated"; 8 pbxproj PRODUCT_BUNDLE_IDENTIFIER com.ivxholdings.appNone → com.ivxholdings.app (fixes prior session botched find-replace); README rewritten to owner-controlled IVX branding with historical note documenting Rork SDK removal.',
    },
    confirm: true,
    confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
  };
  const payload = JSON.stringify(body);
  try {
    const res = execSync(
      `curl -s -m 30 -X POST '${API}' -H 'Content-Type: application/json' -H 'Authorization: Bearer ${OWNER_AT}' -d '${payload.replace(/'/g, "'\\''")}'`,
      { maxBuffer: 1024 * 1024 * 16 }
    ).toString();
    const parsed = JSON.parse(res);
    if (parsed.ok || parsed.success || parsed.sha) {
      ok++;
      console.log(`OK  ${path} → ${parsed.sha || parsed.commitSha || parsed.data?.sha || 'committed'}`);
    } else {
      fail++;
      failures.push({ path, error: (parsed.error || parsed.message || res).slice(0, 200) });
      console.log(`FAIL ${path} → ${parsed.error || parsed.message || res.slice(0, 200)}`);
    }
  } catch (e) {
    fail++;
    failures.push({ path, error: String(e).slice(0, 200) });
    console.log(`ERR ${path} → ${String(e).slice(0, 200)}`);
  }
}

console.log(`\n=== SUMMARY: ${ok} OK, ${fail} FAIL out of ${files.length} ===`);
if (failures.length) {
  console.log('FAILURES:');
  for (const f of failures) console.log(`  ${f.path}: ${f.error}`);
}
SCRIPT
